ANTARCTICA = [(-180,-78),(-160,-78),(-150,-76.5),(-140,-75),(-120,-73.5),(-100,-73),(-80,-73),(-75,-71),(-68,-67),(-62,-64),(-57,-63.5),(-58,-65),(-61,-68),(-62,-72),(-60,-75),(-45,-78),(-35,-77.8),(-25,-75.5),(-15,-72.5),(0,-70),(15,-69.8),(30,-69.5),(45,-67.5),(55,-66.5),(70,-67.5),(72,-70),(80,-67.5),(90,-66.5),(110,-66),(130,-66.2),(145,-67),(160,-69.5),(165,-72),(170,-73),(165,-77),(180,-78),(180,-90),(-180,-90)]

# ---------------------------------------------------------------- noise
def fbm(w, h, base, octaves, seed, gain=.55):
    r = np.random.default_rng(seed); out = np.zeros((h, w), np.float32); amp, tot = 1., 0.
    for o in range(octaves):
        gw, gh = max(2, int(base * 2 ** o)), max(2, int(base * 2 ** o / 2))
        g = r.random((gh, gw + 1)).astype(np.float32); g[:, -1] = g[:, 0]   # wraps in longitude
        im = Image.fromarray(g, 'F').resize((w + w // gw, h), Image.BICUBIC)
        out += np.asarray(im)[:, :w] * amp; tot += amp; amp *= gain
    return out / tot

def xy(lon, lat, w=W, h=H): return ((lon + 180) / 360 * w, (90 - lat) / 180 * h)

def raster(polys, w, h, value=255, holes=()):
    im = Image.new('L', (w, h), 0); d = ImageDraw.Draw(im)
    for poly in polys:
        for shift in (-360, 0, 360):
            d.polygon([xy(lo + shift, la, w, h) for lo, la in poly], fill=value)
    for poly in holes:
        d.polygon([xy(lo, la, w, h) for lo, la in poly], fill=0)
    return im

def _box(a, k, axis, wrap):
    if k < 1: return a
    pad = [(0, 0), (0, 0)]; pad[axis] = (k, k)
    p = np.pad(a, pad, mode='wrap' if wrap else 'edge')
    c = np.cumsum(p, axis=axis, dtype=np.float64)
    c = np.concatenate([np.zeros_like(np.take(c, [0], axis=axis)), c], axis=axis)
    n = a.shape[axis]
    hi = np.take(c, np.arange(2 * k + 1, 2 * k + 1 + n), axis=axis); lo = np.take(c, np.arange(0, n), axis=axis)
    return ((hi - lo) / (2 * k + 1)).astype(np.float32)

def blur(a, r):
    """About a Gaussian of sigma r: three box passes each way, wrapping in longitude."""
    a = a.astype(np.float32)
    k = max(0, int(round(math.sqrt(12 * r * r / 3 + 1) - 1) // 2))
    if k == 0: return a
    for _ in range(3): a = _box(a, k, 1, True)
    for _ in range(3): a = _box(a, k, 0, False)
    return a

def region(LON, LAT, lon0, lon1, lat0, lat1, soft=4):
    """1 inside a lon/lat box, fading over `soft` degrees."""
    a = np.clip((LON - lon0) / soft, 0, 1) * np.clip((lon1 - LON) / soft, 0, 1) * np.clip((LAT - lat0) / soft, 0, 1) * np.clip((lat1 - LAT) / soft, 0, 1)
    return a

def grid(w=W, h=H):
    lon = (np.arange(w) + .5) / w * 360 - 180; lat = 90 - (np.arange(h) + .5) / h * 180
    return np.meshgrid(lon, lat)

def land_mask():
    """The land, at 4096x2048: polygons drawn at twice the size, the coast warped by fractal noise, so it reads as coast and not as a drawing."""
    S = 2
    polys = [NA, GREENLAND, SA, EURASIA, AFRICA, MADAGASCAR, AUSTRALIA, ANTARCTICA] + ISLES_NA + ISLES
    m = np.asarray(raster(polys, W * S, H * S, holes=SEAS)).astype(np.float32) / 255
    m = np.asarray(Image.fromarray(m, 'F').resize((W, H), Image.BILINEAR))
    # warp: sample the mask through a noise displacement (about 0.5 degrees, fractal)
    dx = (fbm(W, H, 24, 6, 11) - .5) * 26; dy = (fbm(W, H, 24, 6, 12) - .5) * 26
    yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
    sx = np.floor(xx + dx).astype(np.int64) % W; sy = np.clip(np.floor(yy + dy), 0, H - 1).astype(np.int64)
    m = m[sy, sx]
    dx = (fbm(W, H, 140, 4, 14) - .5) * 14; dy = (fbm(W, H, 140, 4, 15) - .5) * 14
    sx = np.floor(xx + dx).astype(np.int64) % W; sy = np.clip(np.floor(yy + dy), 0, H - 1).astype(np.int64)
    m = blur(m[sy, sx], 1.5)
    edge = fbm(W, H, 64, 6, 13) * .6 + fbm(W, H, 300, 3, 16) * .4
    return np.clip((m - .5 + (edge - .5) * .55) * 5 + .5, 0, 1)

def earth():
    LON, LAT = grid(); land = land_mask(); A = np.abs(LAT)
    near = blur(land, 18)            # how much land is near: coasts, shelves
    inland = blur(land, 60)          # continentality: deserts sit deep inside
    n1 = fbm(W, H, 16, 7, 21); n2 = fbm(W, H, 48, 6, 22); n3 = fbm(W, H, 128, 4, 23)
    # dryness: the subtropical highs, deep interiors and the named deserts
    dry = np.exp(-((A - 24) / 9) ** 2) * .55 + np.clip(inland - .55, 0, 1) * .9
    for box, k in [((-17, 36, 14, 33), 1.25), ((36, 59, 14, 32), 1.2), ((49, 64, 26, 37), .8), ((67, 76, 23, 30), .7), ((75, 118, 36, 47), .85),
                   ((118, 146, -33, -18), 1.0), ((12, 27, -29, -17), .7), ((-118, -102, 24, 38), .6), ((-72, -67, -40, -16), .7), ((-71, -64, -51, -39), .55),
                   ((50, 80, 39, 50), .5), ((38, 52, 3, 12), .45)]:
        dry += region(LON, LAT, *box, soft=9) * k * (.6 + .8 * n1)
    wet = (region(LON, LAT, -78, -44, -16, 6, 6) + region(LON, LAT, 8, 31, -6, 6, 5) + region(LON, LAT, 95, 152, -10, 10, 5) + region(LON, LAT, -92, -76, 5, 20, 4)
           + region(LON, LAT, 98, 110, 10, 24, 5)) * 1.2
    dry = np.clip(blur(dry - wet, 6) + (n2 - .5) * .9 + (n3 - .5) * .3, 0, 1.6)
    c = lambda h: np.array([int(h[i:i + 2], 16) for i in (1, 3, 5)], np.float32) / 255
    rain, green, savanna, sand, red_sand, boreal, tundra, rock = c('#1e3a16'), c('#3f5a26'), c('#7d7442'), c('#c8ab7a'), c('#c48a55'), c('#2b3a22'), c('#6e6a52'), c('#7c6e5c')
    col = np.zeros((H, W, 3), np.float32)
    t = np.clip(dry, 0, 1)[..., None]
    veg = rain * np.clip(1 - A / 18, 0, 1)[..., None] + green * (1 - np.clip(1 - A / 18, 0, 1))[..., None]
    col = veg * (1 - np.clip(t * 1.7, 0, 1)) + savanna * np.clip(t * 1.7, 0, 1)
    desert = sand * (1 - region(LON, LAT, 112, 150, -36, -14, 6)[..., None] * .8) + red_sand * region(LON, LAT, 112, 150, -36, -14, 6)[..., None] * .8
    col = col * (1 - np.clip((t - .55) * 2.4, 0, 1)) + desert * np.clip((t - .55) * 2.4, 0, 1)
    bo = np.clip((A - 48) / 8, 0, 1)[..., None]; tu = np.clip((A - 63) / 6, 0, 1)[..., None]
    col = col * (1 - bo) + boreal * bo; col = col * (1 - tu) + tundra * tu
    # mountains: darker, browner ridges and snow on the high ones
    mts = (region(LON, LAT, 70, 100, 27, 37, 3) * 1.0 + region(LON, LAT, -80, -66, -45, 5, 2) * .9 + region(LON, LAT, -125, -105, 33, 60, 3) * .7
           + region(LON, LAT, 5, 16, 44.5, 47.5, 1.5) * .8 + region(LON, LAT, 40, 50, 41, 44, 2) * .6 + region(LON, LAT, 88, 105, 30, 40, 3) * .5)
    ridge = blur(np.clip(1 - np.abs(n3 - .5) * 4, 0, 1), 1.5)
    mtn = np.clip(mts * (.4 + ridge * .8), 0, 1)[..., None]
    col = col * (1 - mtn * .5) + rock * mtn * .5
    snow = np.clip(blur(mts, 3) * (.5 + ridge * .7) * 1.3 - .75, 0, 1)[..., None] * .8 * np.clip((np.abs(LAT) - 20) / 10, 0, 1)[..., None]
    col = col + (c('#e8ecef') - col) * snow
    col *= (.82 + .36 * n1[..., None]) * (.9 + .2 * n3[..., None])
    # ice: Antarctica, Greenland, the high Arctic
    ice = np.clip((LAT + 64) / -4, 0, 1) + region(LON, LAT, -56, -18, 64, 84, 2.5) * np.clip(blur(land, 6) * 1.6 - .5, 0, 1) + np.clip((LAT - 76) / 3, 0, 1)
    ice = np.clip(ice + (n2 - .5) * .3, 0, 1)[..., None]
    col = col * (1 - ice) + c('#eef2f5') * (.92 + .08 * n1[..., None]) * ice
    # water: deep navy, teal over the shelves, a little sea ice at the poles
    shelf = np.clip(near * 2.2 - .15, 0, 1)[..., None]
    deep, shallow = c('#06142d'), c('#14465a')
    wat = deep * (1 - shelf) + shallow * shelf
    wat *= (.9 + .2 * n2[..., None])
    seaice = np.clip((A - 72) / 6, 0, 1)[..., None]
    wat = wat * (1 - seaice) + c('#cdd6dc') * seaice
    L = land[..., None]
    out = wat * (1 - L) + col * L
    img = Image.fromarray((np.clip(out, 0, 1) ** (1 / 1.0) * 255).astype(np.uint8), 'RGB')
    img.save(os.path.join(OUT, 'earth_day.png'))
    Image.fromarray((land * 255).astype(np.uint8), 'L').convert('RGB').save(os.path.join(OUT, 'earth_land.png'))
    print('earth_day.png, earth_land.png')
    return land

