def lights(land):
    LON, LAT = grid()
    rr = np.random.default_rng(31)
    pts = []
    for row in CITIES.replace('\n', '').split(';'):
        p = row.split()
        if len(p) == 3: pts.append((float(p[0]), float(p[1]), float(p[2])))
    big = np.zeros((H, W), np.float32)
    def dot(lon, lat, w, r):
        x, y = xy(lon, lat); x, y = int(x) % W, int(np.clip(y, 0, H - 1))
        big[y, x] += w * r
    # each city: a bright core, a ring of suburbs and satellite towns; dense regions connected by roads of tiny lights
    for lon, lat, w in pts:
        dot(lon, lat, w, 1.0)
        for k in range(int(14 + w * 14)):
            d = rr.gamma(1.3, .16 + w * .07); a = rr.random() * 6.283
            dot(lon + math.cos(a) * d / max(.25, math.cos(math.radians(lat))), lat + math.sin(a) * d, w * .12 * rr.random(), 1)
    for i, (lo1, la1, w1) in enumerate(pts):
        for lo2, la2, w2 in pts[i + 1:]:
            dist = math.hypot((lo2 - lo1) * math.cos(math.radians(la1)), la2 - la1)
            if dist < 4.5 and rr.random() < .3:
                n = int(dist * 14)
                for s in range(n):
                    f = s / max(1, n - 1)
                    jitter = math.sin(f * 3.1416) * rr.normal(0, .25)
                    dot(lo1 + (lo2 - lo1) * f + jitter, la1 + (la2 - la1) * f + jitter * .5, (.02 + rr.random() * .06) * min(w1, w2) / 4 * (rr.random() < .5), 1)
    # scattered rural light in the populated belts
    pop = (region(LON, LAT, -98, -70, 28, 46, 4) * .7 + region(LON, LAT, -10, 40, 36, 58, 4) * .8 + region(LON, LAT, 68, 92, 8, 32, 3) * 1.0 +
           region(LON, LAT, 103, 122, 22, 41, 4) * .8 + region(LON, LAT, 30, 33, 22, 31.5, 1) * 1.0 + region(LON, LAT, -52, -35, -30, -5, 4) * .4 +
           region(LON, LAT, 105, 115, -8, -6, 1) * 1.0 + region(LON, LAT, 126, 142, 31, 40, 2) * .8 + region(LON, LAT, 35, 60, 45, 58, 4) * .35)
    spark = (rr.random((H, W)) > .975).astype(np.float32) * rr.random((H, W)).astype(np.float32)
    big += spark * pop * .9
    core = blur(big, .7) * 2.0 + blur(big, 2.0) * 3.0 + blur(big, 6) * 2.4 + blur(big, 14) * 1.2
    core *= np.clip(blur(land, 1.0) * 1.3, 0, 1)
    v = 1 - np.exp(-core * .9)
    Image.fromarray((np.clip(v, 0, 1) * 255).astype(np.uint8), 'L').convert('RGB').save(os.path.join(OUT, 'earth_lights.png'))
    print('earth_lights.png')

def moon():
    w, h = 2048, 1024
    LON, LAT = grid(w, h)
    n1 = fbm(w, h, 12, 7, 41); n2 = fbm(w, h, 64, 5, 42)
    base = .58 + (n1 - .5) * .25 + (n2 - .5) * .1
    mare = np.zeros((h, w), np.float32)
    for lon, lat, r in [(-16, 33, 11), (17, 28, 8), (31, 8, 9), (59, 17, 5.5), (51, -8, 7), (-17, -21, 9), (-55, 15, 18), (-40, 30, 10), (0, 56, 5), (15, 56, 4.5), (-15, 55, 4.5), (35, -15, 4.5), (-39, -24, 4.5), (-25, 5, 6), (-5, 0, 4), (85, 0, 4), (-92, -20, 4)]:
        d = np.hypot((LON - lon) * np.cos(np.radians(LAT)), LAT - lat)
        mare = np.maximum(mare, np.clip(1 - d / r + (n1 - .5) * .9, 0, 1))
    mare = np.clip(mare * 2.2, 0, 1)
    alb = base * (1 - mare * .48)
    # craters: bowls with bright rims and, on the young ones, rays
    rr = np.random.default_rng(43)
    cr = np.zeros((h, w), np.float32)
    for i in range(900):
        lon, lat = rr.random() * 360 - 180, math.degrees(math.asin(rr.random() * 2 - 1)); r = .25 + rr.pareto(2.2) * .5
        r = min(r, 9)
        x0, y0 = xy(lon, lat, w, h); rp = r / 360 * w / max(.2, math.cos(math.radians(lat))); rpy = r / 180 * h
        x1, x2, y1, y2 = int(x0 - rp * 1.6), int(x0 + rp * 1.6) + 1, int(max(0, y0 - rpy * 1.6)), int(min(h, y0 + rpy * 1.6)) + 1
        if y2 <= y1: continue
        xs = np.arange(x1, x2); ys = np.arange(y1, y2); X, Y = np.meshgrid(xs, ys)
        d = np.hypot((X - x0) / rp, (Y - y0) / rpy)
        prof = np.where(d < 1, -.18 * (1 - d * d), .14 * np.exp(-((d - 1.05) / .12) ** 2))
        cr[Y, X % w] += prof
    for lon, lat, r, n in [(-11, -43, 4, 40), (-20, 10, 4, 28), (-38, 8, 2.5, 18)]:
        for k in range(n):
            a = rr.random() * 6.283; L = 12 + rr.random() * 45
            for s in np.linspace(.08, 1, 120):
                lo, la = lon + math.cos(a) * L * s / max(.3, math.cos(math.radians(lat))), lat + math.sin(a) * L * s
                x, y = xy(lo, la, w, h); x, y = int(x) % w, int(np.clip(y, 0, h - 1))
                cr[max(0, y - 1):y + 2, max(0, x - 1):x + 2] += .05 * (1 - s)
    alb = np.clip(alb + blur(cr, .8) * .9, 0, 1)
    Image.fromarray((alb * 255).astype(np.uint8), 'L').convert('RGB').save(os.path.join(OUT, 'moon.png'))
    print('moon.png')

def bands():
    """Latitude (top +90, bottom -90) to colour, 1024 rows, for Jupiter and Saturn. Row 0 is +90."""
    def ramp(stops, n=1024):
        lat = 90 - (np.arange(n) + .5) / n * 180
        out = np.zeros((n, 3), np.float32)
        ls = [s[0] for s in stops]; cs = [np.array([int(s[1][i:i + 2], 16) for i in (1, 3, 5)]) / 255 for s in stops]
        for i, l in enumerate(lat):
            j = np.searchsorted(ls, l)
            if j <= 0: out[i] = cs[0]
            elif j >= len(ls): out[i] = cs[-1]
            else:
                f = (l - ls[j - 1]) / (ls[j] - ls[j - 1]); out[i] = cs[j - 1] * (1 - f) + cs[j] * f
        return out
    # Jupiter, from south to north (ascending latitude): polar haze, temperate belts, the South Equatorial Belt, the Equatorial Zone, the North Equatorial Belt...
    jup = ramp([(-90, '#6f7378'), (-62, '#8a8679'), (-50, '#b7a88f'), (-44, '#9a8670'), (-40, '#d9cbb0'), (-33, '#a28468'), (-29, '#e3d6bd'), (-24, '#c9b393'),
                (-20, '#8c5d3c'), (-14, '#a9714b'), (-9, '#c79b74'), (-7, '#efe6d4'), (0, '#f2e9d6'), (6, '#e8d8bb'), (8, '#9a6a47'), (12, '#7d4f33'), (17, '#a8795a'),
                (19, '#e4d4b6'), (24, '#7f6450'), (26, '#ddcfb5'), (31, '#b49a80'), (36, '#d8c9ae'), (42, '#a18b74'), (50, '#b2a690'), (62, '#878478'), (90, '#6b7076')])
    sat = ramp([(-90, '#80866f'), (-70, '#a49a72'), (-55, '#c8b58b'), (-40, '#d9c79c'), (-30, '#cfb98d'), (-20, '#e3d2a8'), (-10, '#ead9b0'), (0, '#efdfb7'), (8, '#e6d2a6'),
                (16, '#d7bf91'), (24, '#e1cfa4'), (32, '#cbb487'), (40, '#d6c49b'), (50, '#bfae84'), (60, '#a4a07e'), (72, '#8b9a8c'), (90, '#7b8b8a')])
    img = np.stack([jup, sat], 1)  # 1024 x 2 x 3: column 0 Jupiter, column 1 Saturn
    Image.fromarray((img * 255).astype(np.uint8), 'RGB').save(os.path.join(OUT, 'bands.png'))
    print('bands.png')

def rings():
    """Saturn's rings by radius, 2048 texels from 66,900 km (D ring) to 140,500 km (F ring): rgb colour, alpha optical depth as opacity.
    C ring faint and grey-brown, B ring dense and bright, the Cassini Division dark, the A ring medium with the Encke and Keeler gaps, the F ring thin."""
    n = 2048; r0, r1 = 66900., 140500.
    r = r0 + (np.arange(n) + .5) / n * (r1 - r0)
    a = np.zeros(n, np.float32); col = np.zeros((n, 3), np.float32)
    def band(lo, hi, op, c):
        m = (r >= lo) & (r < hi); a[m] = op; col[m] = np.array([int(c[i:i + 2], 16) for i in (1, 3, 5)]) / 255
    band(66900, 74490, .03, '#6b625a')          # D
    band(74490, 91980, .14, '#8e8172')          # C
    band(91980, 117580, .88, '#d8c7a6')         # B
    band(117580, 122170, .06, '#5a5148')        # Cassini Division
    band(122170, 136775, .55, '#c9b99c')        # A
    band(133423, 133745, .02, '#4a443e')        # Encke gap
    band(136487, 136522, .02, '#4a443e')        # Keeler gap
    band(140080, 140280, .35, '#bfb3a0')        # F
    rr = np.random.default_rng(51)
    fine = np.zeros(n, np.float32)
    for f, k in [(3, .3), (11, .25), (37, .2), (120, .15), (400, .12)]:
        g = rr.random(int(f * 8) + 2); fine += np.interp(np.linspace(0, len(g) - 1, n), np.arange(len(g)), g) * k
    fine = fine / fine.max()
    a = np.clip(a * (.65 + fine * .7), 0, 1)
    b = (r > 91980) & (r < 117580); a[b] = np.clip(a[b] + (fine[b] - .5) * .25 + .06 * np.clip((r[b] - 99000) / 8000, 0, 1), 0, .98)
    col *= (.85 + fine[:, None] * .3)
    img = np.zeros((4, n, 4), np.float32); img[:, :, :3] = col; img[:, :, 3] = a
    Image.fromarray((np.clip(img, 0, 1) * 255).astype(np.uint8), 'RGBA').save(os.path.join(OUT, 'rings.png'))
    print('rings.png')

if __name__ == '__main__':
    want = set(sys.argv[1:]) or {'earth', 'lights', 'moon', 'bands', 'rings'}
    land = None
    if 'earth' in want: land = earth()
    if 'lights' in want:
        if land is None: land = np.asarray(Image.open(os.path.join(OUT, 'earth_land.png'))).astype(np.float32) / 255
        lights(land)
    if 'moon' in want: moon()
    if 'bands' in want: bands()
    if 'rings' in want: rings()
